// Enforce: x_ptr must be non-null and readable for at least 2 bytes. Runtime guarantees non-null for inputs.
// To expand coverage, overwrite the 16-bit storage with random bits without changing pointer identity.
// This keeps the input object valid and persistent; we return it as an output to hand it back to the pool.
{
    // Randomize the underlying 16-bit storage via bit pattern copy to avoid UB with cast semantics.
    simsimd_u16_t bits = *FUZZ_PARAM(simsimd_u16_t);
    // __fp16/_Float16 and the fallback 16-bit storage are 2 bytes; memcpy preserves bit-pattern.
    // If simsimd_f16_t is a native 16-bit FP, this still produces a representable value.
    unsigned short tmp = (unsigned short)bits; // ensure 16-bit source for memcpy
    memcpy((void*)f16, &tmp, sizeof(simsimd_f16_t));

    // Call the target function.
    simsimd_f32_t out_f32 = simsimd_f16_to_f32((const simsimd_f16_t*)f16);

    // Sink the result into an attribute to prevent over-optimization and to keep some state.
    // We store whether the converted value is finite as an int flag.
    int finite_flag = (out_f32 == out_f32) && (out_f32 != (simsimd_f32_t)(1.0/0.0)) && (out_f32 != (simsimd_f32_t)(-1.0/0.0));
    FUZZ_SET_ATTR_INT(f16, "last_f16_to_f32_finite", finite_flag);
}
