// Validate contract:
// - result must be within [0, 1]
// - If union has zero bits (all zeros), the function returns 1.
FUZZ_ASSERT(result_value >= 0.0 && result_value <= 1.0, "Jaccard distance must be in [0,1]");

// Check union==0 condition deterministically on the chosen n_words prefix
