// Generate two sorted, unique u16 index arrays from fuzz data and compute their intersection size.
// Enforce: valid pointers when length > 0, ascending order, unique indices, results[0] exists.
{
    std::string a_src = FUZZ_PARAM_STR();
    std::string b_src = FUZZ_PARAM_STR();

    // Derive element counts from available bytes (2 bytes per u16), cap for speed.
    size_t a_cap = a_src.size() / 2;
    size_t b_cap = b_src.size() / 2;
    size_t a_n = a_cap > 512 ? 512 : a_cap;
    size_t b_n = b_cap > 512 ? 512 : b_cap;

    std::vector<simsimd_u16_t> a; a.reserve(a_n);
    for (size_t i = 0; i < a_n; ++i) {
        unsigned v = ((unsigned)(unsigned char)a_src[2*i] << 8) | (unsigned)(unsigned char)a_src[2*i+1];
        a.push_back((simsimd_u16_t)(v & 0xFFFFu));
    }
    std::vector<simsimd_u16_t> b; b.reserve(b_n);
    for (size_t i = 0; i < b_n; ++i) {
        unsigned v = ((unsigned)(unsigned char)b_src[2*i] << 8) | (unsigned)(unsigned char)b_src[2*i+1];
        b.push_back((simsimd_u16_t)(v & 0xFFFFu));
    }

    // Insertion sort (ascending) to avoid relying on <algorithm>.
    auto sort_u16 = [](std::vector<simsimd_u16_t>& v){
        for (size_t i = 1; i < v.size(); ++i) {
            simsimd_u16_t key = v[i];
            size_t j = i;
            while (j > 0 && v[j-1] > key) { v[j] = v[j-1]; --j; }
            v[j] = key;
        }
    };
    sort_u16(a);
    sort_u16(b);

    // Deduplicate consecutive equal elements (set semantics)
    auto dedup_sorted_u16 = [](std::vector<simsimd_u16_t>& v){
        if (v.empty()) return;
        size_t w = 1;
        for (size_t r = 1; r < v.size(); ++r) {
            if (v[r] != v[w-1]) v[w++] = v[r];
        }
        v.resize(w);
    };
    dedup_sorted_u16(a);
    dedup_sorted_u16(b);

    simsimd_distance_t result[1];
    const simsimd_u16_t *ap = a.empty() ? nullptr : a.data();
    const simsimd_u16_t *bp = b.empty() ? nullptr : b.data();
    simsimd_intersect_u16_serial(ap, bp, (simsimd_size_t)a.size(), (simsimd_size_t)b.size(), result);

