    FUZZ_ASSERT(result[0] >= 0.0, "intersection count must be non-negative");
    FUZZ_ASSERT(result[0] <= (simsimd_distance_t)(a.size() < b.size() ? a.size() : b.size()), "intersection count exceeds min(size)");
}
